  fn parse_port_from_url(url: &str) -> i32 {          // -1 == sentinel
      // Step 0: cut fragment then query (equivalently: cut at first '#' or '?')
      let cut = url.find(['#', '?']).unwrap_or(url.len());
      let s = &url[..cut];
      // Step 1: authority
      let Some(i) = s.find("://") else { return -1 };
      let rest = &s[i + 3..];
      let authority = match rest.find('/') { Some(j) => &rest[..j], None => rest };
      let hostport = match authority.find('@') { Some(k) => &authority[k + 1..], None => authority };
      let Some(c) = hostport.find(':') else { return -1 };
      stoi(&hostport[c + 1..])
  }
  fn stoi(port_str: &str) -> i32 {                    // std::stoi, base 10, try/catch -> -1
      let b = port_str.as_bytes(); let mut i = 0;
      while i < b.len() && matches!(b[i], b' '|b'\t'|b'\n'|0x0B|0x0C|b'\r') { i += 1; }
      let neg = match b.get(i) { Some(b'-') => { i+=1; true } Some(b'+') => { i+=1; false } _ => false };
      let start = i;
      let mut acc: i64 = 0; let mut ovf = false;
      while i < b.len() && b[i].is_ascii_digit() {
          if !ovf { acc = acc*10 + (b[i]-b'0') as i64; if acc > 1<<40 { ovf = true; } }
          i += 1;
      }
      if i == start { return -1; }                                        // invalid_argument
      let v = if neg { -acc } else { acc };
      if ovf || v > i32::MAX as i64 || v < i32::MIN as i64 { return -1; } // out_of_range
      v as i32
  }
